INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Zustandsdiagramm nur für komplexe Systeme sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Zustände klärbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Zustandsdiagramm?', 3, '[{"text": "Zustandswechsel darstellen", "correct": true, "because": "Zeigt Übergänge klar"}, {"text": "Modulstruktur zeigen", "correct": false, "because": "Paketdiagramm-Thema"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Zustandsdiagramm?', 5, '[{"text": "Zustände", "correct": true, "because": "Repräsentieren Systemstatus"}, {"text": "Übergänge", "correct": true, "because": "Zeigen Zustandswechsel"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zustandsdiagramme zeigen dynamische Zustände. b) Sie ersetzen Sequenzdiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sequenz zeigt Abläufe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Zustandsdiagramm?', 4, '[{"text": "Zustandsübergänge", "correct": false, "because": "Kern des Diagramms"}, {"text": "Start-/Endzustände", "correct": false, "because": "Definieren Ablauf"}, {"text": "UI-Design", "correct": true, "because": "Kein Zustandsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Zustandsdiagramm auch Softwaremodule zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Zustände"}, {"text": "Ja", "correct": false, "because": "Komponentendiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für einen Zustand?', 3, '[{"text": "Rechteck mit abgerundeten Ecken", "correct": true, "because": "UML-Standard"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}, {"text": "Knoten", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern ein Zustandsdiagramm?', 5, '[{"text": "Ereignisse", "correct": true, "because": "Lösen Übergänge aus"}, {"text": "Bedingungen", "correct": true, "because": "Steuern Übergänge"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Zustandsdiagramme sind für Zustandswechsel. b) Sie zeigen Hardwarezuordnung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Zustandsdiagramm?', 4, '[{"text": "Zustände", "correct": false, "because": "Kern der Darstellung"}, {"text": "Übergänge", "correct": false, "because": "Zeigen Wechsel"}, {"text": "Netzwerkprotokolle", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Zustandsdiagramm statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Zeigt dynamische Zustandswechsel"}, {"text": "Ja", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen nutze ich im Zustandsdiagramm?', 4, '[{"text": "Übergänge", "correct": true, "because": "Verbinden Zustände"}, {"text": "Ereignisse", "correct": true, "because": "Lösen Übergänge aus"}, {"text": "Abhängigkeiten", "correct": false, "because": "Paketdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Zustandsdiagramme nur für Software sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für physische Systeme"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Zustandsdiagramm?', 3, '[{"text": "Klarheit der Übergänge", "correct": true, "because": "Verständnis fördern"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Visuelle Effekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zustandsdiagramme sind UML-Teil. b) Sie zeigen Modulstruktur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modulstruktur ist Komponentendiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Zustandsdiagramm?', 5, '[{"text": "Zustandsübersicht", "correct": true, "because": "Klarheit über Status"}, {"text": "Verhaltensplanung", "correct": true, "because": "Übergänge sichtbar"}, {"text": "Datenflussanalyse", "correct": false, "because": "Anderes Diagramm"}, {"text": "Hardwarezuordnung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Zustandsdiagramm unwichtig?', 3, '[{"text": "Zustandswechsel", "correct": false, "because": "Kern der Darstellung"}, {"text": "Ereignisse", "correct": false, "because": "Lösen Übergänge aus"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Zustandsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Zustandsdiagramm auch Abläufe?', 3, '[{"text": "Ja", "correct": true, "because": "Übergänge sind Abläufe"}, {"text": "Nein", "correct": false, "because": "Dynamische Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zustandsdiagramme für Tests nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Testen Zustandswechsel"}, {"text": "Nein", "correct": false, "because": "Testfälle ableitbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für einen Zustandsübergang?', 4, '[{"text": "Pfeil", "correct": true, "because": "Verbindet Zustände"}, {"text": "Rechteck", "correct": false, "because": "Nur Zustände"}, {"text": "Knoten", "correct": false, "because": "Verteilungsdiagramm"}]');
